document.addEventListener('DOMContentLoaded',()=>{const days=document.querySelector('.route-days'),side=document.querySelector('.side');if(!days||!side)return;const saved=localStorage.getItem('angra-route');if(saved)days.innerHTML=saved;const persist=()=>localStorage.setItem('angra-route',days.innerHTML);new MutationObserver(persist).observe(days,{childList:true,subtree:true,characterData:true});const reset=document.createElement('button');reset.className='trip-reset';reset.textContent='Refazer briefing';reset.onclick=()=>{localStorage.removeItem('angra-briefing');localStorage.removeItem('angra-route');location.reload()};side.appendChild(reset);const s=document.createElement('style');s.textContent='.trip-reset{width:100%;margin-top:10px;border:0;background:transparent;color:#66808b;font-size:11px;text-decoration:underline;cursor:pointer}';document.head.appendChild(s)});
